1	import { db } from "./db";
2	import { MODEL_RATES } from "./models";
3	
4	// ── The anti-bill-shock contract ──────────────────────────────────────────
5	// 1. A credit is a fixed, published amount of real model spend. No mystery units.
6	// 2. We charge from METERED tokens after a build succeeds — never a flat guess.
7	// 3. A build that fails is recorded with its true cost and charged ZERO.
8	// This is Kodely's clearest wedge against the category (see the board's
9	// "credit bill-shock" differentiation cards), so it lives in one small module.
10	
11	/** One credit = $0.002 of underlying model spend (500 credits = $1). */
12	export const MICROS_PER_CREDIT = 2_000;
13	
14	/**
15	 * New accounts start with enough to build and iterate on a real page.
16	 * Sized from measured real costs (2026-08-17): a full first build runs
17	 * ~$0.29 (144 credits), a follow-up edit ~$0.34 (172 credits) on Sonnet 5 —
18	 * 750 covers roughly one build plus 2-3 real edits.
19	 */
20	export const SIGNUP_GRANT = 750;
21	
22	export type Usage = {
23	  inputTokens: number;
24	  outputTokens: number;
25	  cacheReadTokens: number;
26	  cacheWriteTokens: number;
27	};
28	
29	/**
30	 * Micro-dollars of real model spend for a given usage on a given model.
31	 * MODEL_RATES stores USD per MILLION tokens, which — numerically — is
32	 * already USD-per-token expressed in micro-dollars (1e-6 USD = 1 microUSD).
33	 * So `rate * tokens` IS the cost in micros directly; do NOT also divide by
34	 * 1e6, that computes cost in whole dollars instead and silently floors every
35	 * build under $0.50 to 0 (which is exactly the bug this comment replaced —
36	 * caught 2026-08-17 when a real ~$0.22 build was charged only 1 credit).
37	 */
38	export function costMicros(model: string, usage: Usage): number {
39	  const rate = MODEL_RATES[model] ?? MODEL_RATES.default;
40	  const perToken = (perMTok: number, tokens: number) => perMTok * tokens;
41	  return Math.round(
42	    perToken(rate.input, usage.inputTokens) +
43	      perToken(rate.output, usage.outputTokens) +
44	      perToken(rate.cacheRead, usage.cacheReadTokens) +
45	      perToken(rate.cacheWrite, usage.cacheWriteTokens),
46	  );
47	}
48	
49	export function creditsFor(micros: number): number {
50	  return Math.max(1, Math.ceil(micros / MICROS_PER_CREDIT));
51	}
52	
53	export async function getBalance(userId: string): Promise<number> {
54	  const latest = await db.creditLedger.findFirst({
55	    where: { userId },
56	    orderBy: { createdAt: "desc" },
57	  });
58	  return latest?.balanceAfter ?? 0;
59	}
60	
61	export async function grantCredits(userId: string, amount: number, reason: string) {
62	  const balance = await getBalance(userId);
63	  return db.creditLedger.create({
64	    data: { userId, delta: amount, reason, balanceAfter: balance + amount },
65	  });
66	}
67	
68	/**
69	 * Charge for a SUCCESSFUL build. Never call this on a failed build — the whole
70	 * promise to the customer is that broken output is free.
71	 */
72	export async function chargeForBuild(userId: string, buildId: string, credits: number) {
73	  const balance = await getBalance(userId);
74	  await db.creditLedger.create({
75	    data: {
76	      userId,
77	      delta: -credits,
78	      reason: "build",
79	      buildId,
80	      balanceAfter: balance - credits,
81	    },
82	  });
83	  return balance - credits;
84	}
85	
86	/**
87	 * Pre-flight estimate shown BEFORE the user spends anything. Deliberately a
88	 * range derived from observed build sizes, not a fake precise number.
89	 *
90	 * Numbers corrected 2026-08-21. The previous 8-30 / 3-15 ranges predated the
91	 * costMicros fix and understated real spend by roughly 5-18x — on a product
92	 * whose headline promise is no bill shock, an estimate that low is worse than
93	 * showing nothing. These match the measured figures cited on SIGNUP_GRANT
94	 * (~144 credits for a first build, ~172 for a follow-up edit), widened to a
95	 * range because real builds vary with page count and iteration.
96	 */
97	export function estimateCredits(kind: "create" | "edit"): { low: number; high: number } {
98	  return kind === "create" ? { low: 90, high: 220 } : { low: 60, high: 260 };
99	}
100	
101	/** Fallback when a user has no build history to average — see SIGNUP_GRANT. */
102	const TYPICAL_BUILD_CREDITS = 150;
103	
104	/**
105	 * What a build actually costs THIS user, averaged over their recent successful
106	 * builds. Personal history beats a global constant: someone building one-page
107	 * sites and someone building ten-page sites deserve different answers to
108	 * "how many builds do I have left?".
109	 */
110	export async function averageBuildCredits(userId: string): Promise<number> {
111	  const recent = await db.build.findMany({
112	    where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
113	    orderBy: { createdAt: "desc" },
114	    take: 10,
115	    select: { creditsCharged: true },
116	  });
117	  if (recent.length === 0) return TYPICAL_BUILD_CREDITS;
118	  const total = recent.reduce((sum, b) => sum + b.creditsCharged, 0);
119	  return Math.max(1, Math.round(total / recent.length));
120	}
121	
122	// ── Self-imposed spend cap ────────────────────────────────────────────────
123	// Point 4 of the anti-bill-shock contract. The three rules above stop us from
124	// OVERCHARGING for a given build; none of them stop a user from running fifty
125	// builds in an afternoon and being genuinely shocked by the total. A ceiling
126	// the user sets themselves is the honest answer, and it is the one guard a
127	// competitor's $607-against-a-$25-plan incident would have needed.
128	//
129	// Rolling 30 days, not calendar month, so there is no "reset day" to game and
130	// no cliff where a cap silently stops protecting someone mid-month.
131	
132	const CAP_WINDOW_DAYS = 30;
133	
134	export type SpendCapStatus = {
135	  /** NULL when the user has set no cap. */
136	  cap: number | null;
137	  spent: number;
138	  /** Credits still available under the cap; Infinity when uncapped. */
139	  remaining: number;
140	  reached: boolean;
141	};
142	
143	/** Credits spent on builds in the rolling window. Grants are excluded. */
144	export async function spentInWindow(userId: string): Promise<number> {
145	  const since = new Date(Date.now() - CAP_WINDOW_DAYS * 24 * 60 * 60 * 1000);
146	  const { _sum } = await db.creditLedger.aggregate({
147	    where: { userId, createdAt: { gte: since }, delta: { lt: 0 } },
148	    _sum: { delta: true },
149	  });
150	  // Deltas are negative for spend; report it as a positive number.
151	  return Math.abs(_sum.delta ?? 0);
152	}
153	
154	export async function getSpendCapStatus(userId: string): Promise<SpendCapStatus> {
155	  const user = await db.user.findUnique({
156	    where: { id: userId },
157	    select: { spendCapCredits: true },
158	  });
159	  const cap = user?.spendCapCredits ?? null;
160	
161	  if (cap === null) {
162	    return { cap: null, spent: 0, remaining: Infinity, reached: false };
163	  }
164	
165	  const spent = await spentInWindow(userId);
166	  return { cap, spent, remaining: Math.max(0, cap - spent), reached: spent >= cap };
167	}
