1	import { redirect } from "next/navigation";
2	import Link from "next/link";
3	import { getCurrentUser } from "@/lib/auth";
4	import { getSpendCapStatus, spentInWindow } from "@/lib/credits";
5	import SpendCapForm from "./SpendCapForm";
6	
7	export const dynamic = "force-dynamic";
8	
9	export default async function SettingsPage() {
10	  const user = await getCurrentUser();
11	  if (!user) redirect("/login");
12	
13	  const cap = await getSpendCapStatus(user.id);
14	  // getSpendCapStatus skips the spend query when uncapped (nothing to compare
15	  // against), but this page shows recent spend either way.
16	  const spent = cap.cap === null ? await spentInWindow(user.id) : cap.spent;
17	
18	  return (
19	    <div className="mx-auto max-w-2xl px-6 py-10">
20	      <div className="mb-8">
21	        <Link
22	          href="/dashboard"
23	          className="text-sm text-black/60 underline underline-offset-2 hover:no-underline dark:text-white/60"
24	        >
25	          ← Back
26	        </Link>
27	        <h1 className="mt-3 text-lg font-semibold tracking-tight">Settings</h1>
28	        <p className="text-sm text-black/60 dark:text-white/60">{user.email}</p>
29	      </div>
30	
31	      <SpendCapForm initialCap={cap.cap} spent={spent} />
32	    </div>
33	  );
34	}
