1	import { getCurrentUser } from "@/lib/auth";
2	import { db } from "@/lib/db";
3	import { getSpendCapStatus } from "@/lib/credits";
4	
5	export const dynamic = "force-dynamic";
6	
7	// The user's own ceiling on 30-day spend. Deliberately theirs to set and
8	// theirs to remove — a cap we imposed would be a plan limit, which is the
9	// thing that causes bill shock rather than the thing that prevents it.
10	
11	/** Guards against a typo'd cap so large it protects nobody. */
12	const MAX_CAP = 1_000_000;
13	
14	export async function GET() {
15	  const user = await getCurrentUser();
16	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
17	
18	  const status = await getSpendCapStatus(user.id);
19	  // Infinity is not valid JSON — it serializes to null, which the client
20	  // would then have to guess the meaning of. Send the cap and let it derive.
21	  return Response.json({
22	    cap: status.cap,
23	    spent: status.cap === null ? null : status.spent,
24	    reached: status.reached,
25	  });
26	}
27	
28	export async function PUT(req: Request) {
29	  const user = await getCurrentUser();
30	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
31	
32	  const body = (await req.json().catch(() => null)) as { cap?: number | null } | null;
33	  const raw = body?.cap;
34	
35	  // null clears the cap. Anything else must be a positive whole number.
36	  let cap: number | null = null;
37	  if (raw !== null && raw !== undefined) {
38	    if (typeof raw !== "number" || !Number.isFinite(raw) || !Number.isInteger(raw) || raw < 1) {
39	      return Response.json({ error: "Enter a whole number of credits, or clear the cap." }, { status: 400 });
40	    }
41	    if (raw > MAX_CAP) {
42	      return Response.json({ error: `Caps above ${MAX_CAP.toLocaleString()} credits aren't useful — leave it off instead.` }, { status: 400 });
43	    }
44	    cap = raw;
45	  }
46	
47	  await db.user.update({ where: { id: user.id }, data: { spendCapCredits: cap } });
48	
49	  const status = await getSpendCapStatus(user.id);
50	  return Response.json({
51	    cap: status.cap,
52	    spent: status.cap === null ? null : status.spent,
53	    reached: status.reached,
54	  });
55	}
