1	import { randomBytes } from "node:crypto";
2	
3	export const dynamic = "force-dynamic";
4	
5	const STATE_COOKIE = "kodely_google_oauth_state";
6	
7	// Inert until real GOOGLE_CLIENT_ID/GOOGLE_CLIENT_SECRET are configured —
8	// same "ships now, activates when credentials land" pattern already used
9	// for Stripe billing (see lib/stripe.ts). Redirect_uri is derived from the
10	// request's own origin so this works on staging and prod without
11	// hardcoding either — both origins' /api/auth/google/callback must be
12	// added as authorized redirect URIs in the Google Cloud OAuth client.
13	// Behind nginx, req.url reflects the internal 127.0.0.1:PORT the proxy
14	// forwards to, not the public host the visitor actually used — the same
15	// Host-header derivation the publish route already relies on.
16	function originFromRequest(req: Request): string {
17	  const host = req.headers.get("host");
18	  if (!host) return new URL(req.url).origin;
19	  // The Cloudflare -> host-nginx -> VM-nginx chain runs Flexible SSL (each
20	  // hop is plain HTTP even though the real visitor connection is HTTPS), so
21	  // X-Forwarded-Proto gets clobbered along the way and can't be trusted —
22	  // same reason the publish route hardcodes https rather than deriving it.
23	  return `https://${host}`;
24	}
25	
26	export async function GET(req: Request) {
27	  const clientId = process.env.GOOGLE_CLIENT_ID;
28	  const origin = originFromRequest(req);
29	
30	  if (!clientId) {
31	    return Response.redirect(`${origin}/login?error=google_not_configured`, 302);
32	  }
33	
34	  const state = randomBytes(24).toString("base64url");
35	  const redirectUri = `${origin}/api/auth/google/callback`;
36	
37	  const authUrl = new URL("https://accounts.google.com/o/oauth2/v2/auth");
38	  authUrl.searchParams.set("client_id", clientId);
39	  authUrl.searchParams.set("redirect_uri", redirectUri);
40	  authUrl.searchParams.set("response_type", "code");
41	  authUrl.searchParams.set("scope", "openid email profile");
42	  authUrl.searchParams.set("state", state);
43	  authUrl.searchParams.set("prompt", "select_account");
44	
45	  // Response.redirect()'s headers are immutable in this runtime — build the
46	  // redirect by hand so the state cookie can actually be attached to it.
47	  return new Response(null, {
48	    status: 302,
49	    headers: {
50	      Location: authUrl.toString(),
51	      "Set-Cookie": `${STATE_COOKIE}=${state}; Path=/; HttpOnly; SameSite=Lax; Max-Age=600${
52	        process.env.NODE_ENV === "production" ? "; Secure" : ""
53	      }`,
54	    },
55	  });
56	}
