1	import { cookies } from "next/headers";
2	import { db } from "@/lib/db";
3	import { createSession } from "@/lib/auth";
4	import { grantCredits, SIGNUP_GRANT } from "@/lib/credits";
5	import { createSeedProject } from "@/lib/seed-project";
6	import { track, EVENTS } from "@/lib/events";
7	
8	export const dynamic = "force-dynamic";
9	
10	const STATE_COOKIE = "kodely_google_oauth_state";
11	
12	type GoogleTokenResponse = { access_token?: string; id_token?: string; error?: string };
13	type GoogleUserInfo = { sub: string; email?: string; email_verified?: boolean; name?: string };
14	
15	// Behind nginx, req.url reflects the internal 127.0.0.1:PORT the proxy
16	// forwards to, not the public host the visitor actually used — must match
17	// exactly what /start sent as redirect_uri, or Google rejects the exchange.
18	function originFromRequest(req: Request): string {
19	  const host = req.headers.get("host");
20	  if (!host) return new URL(req.url).origin;
21	  // See the matching comment in the /start route — X-Forwarded-Proto isn't
22	  // trustworthy across this app's Flexible-SSL proxy chain.
23	  return `https://${host}`;
24	}
25	
26	export async function GET(req: Request) {
27	  const url = new URL(req.url);
28	  const origin = originFromRequest(req);
29	  const code = url.searchParams.get("code");
30	  const state = url.searchParams.get("state");
31	
32	  const jar = await cookies();
33	  const expectedState = jar.get(STATE_COOKIE)?.value;
34	  jar.delete(STATE_COOKIE);
35	
36	  const clientId = process.env.GOOGLE_CLIENT_ID;
37	  const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
38	
39	  if (!clientId || !clientSecret) {
40	    return Response.redirect(`${origin}/login?error=google_not_configured`, 302);
41	  }
42	  if (!code || !state || state !== expectedState) {
43	    return Response.redirect(`${origin}/login?error=google_failed`, 302);
44	  }
45	
46	  try {
47	    const tokenRes = await fetch("https://oauth2.googleapis.com/token", {
48	      method: "POST",
49	      headers: { "Content-Type": "application/x-www-form-urlencoded" },
50	      body: new URLSearchParams({
51	        code,
52	        client_id: clientId,
53	        client_secret: clientSecret,
54	        redirect_uri: `${origin}/api/auth/google/callback`,
55	        grant_type: "authorization_code",
56	      }),
57	    });
58	    const tokens = (await tokenRes.json()) as GoogleTokenResponse;
59	    if (!tokenRes.ok || !tokens.access_token) {
60	      return Response.redirect(`${origin}/login?error=google_failed`, 302);
61	    }
62	
63	    const infoRes = await fetch("https://openidconnect.googleapis.com/v1/userinfo", {
64	      headers: { Authorization: `Bearer ${tokens.access_token}` },
65	    });
66	    const info = (await infoRes.json()) as GoogleUserInfo;
67	    if (!infoRes.ok || !info.email || !info.email_verified) {
68	      return Response.redirect(`${origin}/login?error=google_failed`, 302);
69	    }
70	
71	    const email = info.email.trim().toLowerCase();
72	    let user = await db.user.findUnique({ where: { googleId: info.sub } });
73	
74	    if (!user) {
75	      // Link to an existing email/password account rather than creating a
76	      // second one for the same person.
77	      const existing = await db.user.findUnique({ where: { email } });
78	      if (existing) {
79	        user = await db.user.update({ where: { id: existing.id }, data: { googleId: info.sub } });
80	      } else {
81	        user = await db.user.create({
82	          data: { email, googleId: info.sub, name: info.name?.trim() || null },
83	        });
84	        await grantCredits(user.id, SIGNUP_GRANT, "signup_grant");
85	        await createSeedProject(user.id);
86	        // Only on a genuinely new account — linking Google to an existing
87	        // email/password user is not a signup and must not inflate the funnel.
88	        track(EVENTS.signedUp, { userId: user.id, props: { method: "google" } });
89	      }
90	    }
91	
92	    await createSession(user.id);
93	    return Response.redirect(`${origin}/continue`, 302);
94	  } catch {
95	    return Response.redirect(`${origin}/login?error=google_failed`, 302);
96	  }
97	}
