71	 * publish, counted in DISTINCT USERS rather than events. Counting events would
72	 * let one enthusiastic user look like retention.
73	 */
74	export async function activationFunnel(sinceDays = 30): Promise<FunnelStep[]> {
75	  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60 * 1000);
76	
77	  const steps: { step: string; event: EventName }[] = [
78	    { step: "Signed up", event: EVENTS.signedUp },
79	    { step: "Created a project", event: EVENTS.projectCreated },
80	    { step: "Built successfully", event: EVENTS.buildSucceeded },
81	    { step: "Published a site", event: EVENTS.sitePublished },
82	  ];
83	
84	  const out: FunnelStep[] = [];
85	  let previous: number | null = null;
86	
