89	      where: { name: s.event, createdAt: { gte: since }, userId: { not: null } },
90	      distinct: ["userId"],
91	      select: { userId: true },
92	    });
93	    const users = rows.length;
94	    out.push({
95	      ...s,
96	      users,
97	      pctOfPrevious: previous === null || previous === 0 ? null : Math.round((users / previous) * 1000) / 10,
98	    });
99	    previous = users;
100	  }
101	
102	  return out;
103	}
