import { getCurrentUser } from "@/lib/auth";
import {
  accountTooNew,
  hasClaimed,
  isPlatformConfigured,
  MIN_ACCOUNT_AGE_HOURS,
  pendingClaim,
  recordPending,
  UNVERIFIED_HOLD_HOURS,
} from "../../_lib";
import {
  handleAlreadySpokenFor,
  handleIdentity,
  isUnverifiedPlatform,
  normalizeHandle,
} from "../_unverified";

export const dynamic = "force-dynamic";

// Step 1 of the UNVERIFIED path — see ../_unverified.ts for what this does and
// does not prove. This endpoint grants ZERO credits. It only records that the
// user claimed a handle, starting the hold clock.

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });

  const body = (await req.json().catch(() => null)) as {
    platform?: unknown;
    handle?: unknown;
  } | null;

  const platform = body?.platform;
  if (!isUnverifiedPlatform(platform)) {
    // "discord" lands here too, and should: it has its own verified route and
    // must never be claimable by typing a handle.
    return Response.json({ error: "Unknown reward." }, { status: 400 });
  }
  if (!isPlatformConfigured(platform)) {
    return Response.json({ error: "That reward isn't available." }, { status: 404 });
  }

  if (accountTooNew(user.createdAt)) {
    return Response.json(
      {
        error: `Rewards unlock ${MIN_ACCOUNT_AGE_HOURS} hours after signup. Come back tomorrow.`,
      },
      { status: 403 },
    );
  }

  if (typeof body?.handle !== "string") {
    return Response.json({ error: "Enter your username." }, { status: 400 });
  }
  const handle = normalizeHandle(platform, body.handle);
  if (handle === null) {
    return Response.json({ error: "That doesn't look like a valid username." }, { status: 400 });
  }

  if (await hasClaimed(user.id, platform)) {
    return Response.json({ error: "You've already claimed this one." }, { status: 409 });
  }
  if (await pendingClaim(user.id, platform)) {
    return Response.json(
      { error: "You've already connected an account for this reward." },
      { status: 409 },
    );
  }

  const hash = handleIdentity(platform, handle);
  if (hash === null) {
    console.error("[rewards] KODELY_REWARDS_ID_SALT is not set — refusing to record a claim.");
    return Response.json({ error: "Rewards are unavailable right now." }, { status: 503 });
  }

  // One external identity, one grant, across every Kodely account.
  if (await handleAlreadySpokenFor(platform, hash)) {
    return Response.json(
      { error: "That account has already been used for this reward." },
      { status: 409 },
    );
  }

  await recordPending(user.id, platform, hash);

  const readyAt = new Date(Date.now() + UNVERIFIED_HOLD_HOURS * 3_600_000);
  return Response.json({ state: "pending", readyAt: readyAt.toISOString() });
}

import { getCurrentUser } from "@/lib/auth";
import {
  accountTooNew,
  grantReward,
  hashFromPendingReason,
  isPlatformConfigured,
  MIN_ACCOUNT_AGE_HOURS,
  pendingClaim,
  UNVERIFIED_HOLD_HOURS,
} from "../../_lib";
import { isUnverifiedPlatform } from "../_unverified";

export const dynamic = "force-dynamic";

// Step 2 of the UNVERIFIED path — see ../_unverified.ts. This DOES move money,
// so every gate is re-checked here rather than trusted from step 1: the hold
// is recomputed from the pending row's own createdAt (not from anything the
// client sends), and the identity hash comes out of the stored reason string
// rather than being re-derived from a handle the client could swap.

export async function POST(req: Request) {
  const user = await getCurrentUser();
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });

  const body = (await req.json().catch(() => null)) as { platform?: unknown } | null;
  const platform = body?.platform;

  if (!isUnverifiedPlatform(platform)) {
    return Response.json({ error: "Unknown reward." }, { status: 400 });
  }
  if (!isPlatformConfigured(platform)) {
    return Response.json({ error: "That reward isn't available." }, { status: 404 });
  }
  if (accountTooNew(user.createdAt)) {
    return Response.json(
      { error: `Rewards unlock ${MIN_ACCOUNT_AGE_HOURS} hours after signup.` },
      { status: 403 },
    );
  }

  const pending = await pendingClaim(user.id, platform);
  if (!pending) {
    return Response.json({ error: "Connect an account first." }, { status: 409 });
  }

  const readyAt = pending.createdAt.getTime() + UNVERIFIED_HOLD_HOURS * 3_600_000;
  if (Date.now() < readyAt) {
    return Response.json(
      { error: "Not ready yet.", readyAt: new Date(readyAt).toISOString() },
      { status: 425 },
    );
  }

  const hash = hashFromPendingReason(pending.reason);
  if (hash === null) {
    console.error(`[rewards] malformed pending reason for user ${user.id}: ${pending.reason}`);
    return Response.json({ error: "Rewards are unavailable right now." }, { status: 503 });
  }

  const result = await grantReward(user.id, platform, hash);
  if (!result.ok) {
    const status =
      result.reason === "already_claimed" || result.reason === "identity_already_used"
        ? 409
        : result.reason === "velocity_tripped"
          ? 429
          : 503;
    return Response.json({ error: messageFor(result.reason), state: result.reason }, { status });
  }

  return Response.json({ state: "claimed", credits: result.credits });
}

function messageFor(reason: string): string {
  switch (reason) {
    case "already_claimed":
      return "You've already claimed this one.";
    case "identity_already_used":
      return "That account has already been used for this reward.";
    case "velocity_tripped":
      return "Reward claims are paused for a moment. Try again shortly.";
    default:
      return "Rewards are unavailable right now.";
  }
}

import { getCurrentUser } from "@/lib/auth";
import { rewardStatuses } from "./_lib";

export const dynamic = "force-dynamic";

// Read-only view of this user's rewards. Returns an empty list — never an
// error — when nothing is configured, so the settings page can simply render
// nothing rather than having to special-case a failure.

export async function GET() {
  const user = await getCurrentUser();
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });

  return Response.json({ rewards: await rewardStatuses(user) });
}

import { randomBytes } from "node:crypto";
import { getCurrentUser } from "@/lib/auth";
import {
  accountTooNew,
  discordConfig,
  hasClaimed,
  identitySecret,
  originFromRequest,
} from "../../_lib";

export const dynamic = "force-dynamic";

// ── The VERIFIED path, step 1 ─────────────────────────────────────────────
//
// Discord is the one platform of the four that can actually be checked. The
// OAuth2 `guilds.members.read` scope lets us ask Discord itself, first-party,
// whether the authorizing user is a member of ONE specific guild — ours. It is
// narrower than the `guilds` scope, which would hand us the full list of every
// server the user is in; we have no business seeing that, and asking for it
// would make the consent screen alarming for no gain.
//
// Nothing here is trusted from the browser. The user identity comes from the
// session cookie, the guild membership comes from Discord's API, and the two
// are tied together by a state cookie that also pins WHICH Kodely user started
// the flow — so a callback replayed into a different session cannot land.

const STATE_COOKIE = "kodely_discord_reward_state";

export async function GET(req: Request) {
  const origin = originFromRequest(req);
  const user = await getCurrentUser();
  if (!user) return Response.redirect(`${origin}/login`, 302);

  const config = discordConfig();
  // Unconfigured is not an error — the reward simply does not exist. The
  // settings page will not have shown a button; a hand-typed URL lands here.
  if (!config || identitySecret() === null) {
    console.error(
      "[rewards] Discord reward hit without full config (KODELY_DISCORD_CLIENT_ID / _SECRET / _GUILD_ID, KODELY_REWARDS_ID_SALT).",
    );
    return Response.redirect(`${origin}/settings?reward=unavailable`, 302);
  }

  if (await hasClaimed(user.id, "discord")) {
    return Response.redirect(`${origin}/settings?reward=already`, 302);
  }
  if (accountTooNew(user.createdAt)) {
    return Response.redirect(`${origin}/settings?reward=too_new`, 302);
  }

  // The state cookie carries the user id alongside the nonce. Both are
  // re-checked in the callback: the nonce proves the round trip started here,
  // the user id proves it started in THIS session.
  const nonce = randomBytes(24).toString("base64url");
  const state = `${nonce}.${user.id}`;

  const authUrl = new URL("https://discord.com/oauth2/authorize");
  authUrl.searchParams.set("client_id", config.clientId);
  authUrl.searchParams.set("redirect_uri", `${origin}/api/rewards/discord/callback`);
  authUrl.searchParams.set("response_type", "code");
  authUrl.searchParams.set("scope", "identify guilds.members.read");
  authUrl.searchParams.set("state", state);
  authUrl.searchParams.set("prompt", "consent");

  // Response.redirect()'s headers are immutable in this runtime — build the
  // redirect by hand so the state cookie can be attached (same reason the
  // Google OAuth start route does this).
  return new Response(null, {
    status: 302,
    headers: {
      Location: authUrl.toString(),
      "Set-Cookie": `${STATE_COOKIE}=${state}; Path=/; HttpOnly; SameSite=Lax; Max-Age=600${
        process.env.NODE_ENV === "production" ? "; Secure" : ""
      }`,
    },
  });
}

import { timingSafeEqual } from "node:crypto";
import { cookies } from "next/headers";
import { getCurrentUser } from "@/lib/auth";
import {
  accountTooNew,
  discordConfig,
  grantReward,
  identityHash,
  originFromRequest,
} from "../../_lib";

export const dynamic = "force-dynamic";

// ── The VERIFIED path, step 2 ─────────────────────────────────────────────
//
// This is the only place in the whole feature where a grant is backed by an
// actual third-party check. The claim "this person is in our Discord" is
// answered by Discord, about the account that just authenticated to Discord,
// on a server-to-server call the browser never touches.
//
// The access token is used once, here, and never stored — not in the ledger,
// not in a cookie, not in a log. The only thing that survives this request is
// an HMAC of the Discord user id (see identityHash in ../../_lib.ts).

const STATE_COOKIE = "kodely_discord_reward_state";
const API = "https://discord.com/api/v10";

type TokenResponse = { access_token?: string; error?: string };
type DiscordUser = { id?: string };

function done(origin: string, outcome: string): Response {
  return Response.redirect(`${origin}/settings?reward=${outcome}`, 302);
}

/** Constant-time compare that tolerates unequal lengths without throwing. */
function safeEqual(a: string, b: string): boolean {
  const bufA = Buffer.from(a);
  const bufB = Buffer.from(b);
  if (bufA.length !== bufB.length) return false;
  return timingSafeEqual(bufA, bufB);
}

export async function GET(req: Request) {
  const origin = originFromRequest(req);
  const url = new URL(req.url);

  const jar = await cookies();
  const expectedState = jar.get(STATE_COOKIE)?.value;
  jar.delete(STATE_COOKIE);

  const user = await getCurrentUser();
  if (!user) return Response.redirect(`${origin}/login`, 302);

  const config = discordConfig();
  if (!config) {
    console.error("[rewards] Discord callback reached with no Discord config.");
    return done(origin, "unavailable");
  }

  const code = url.searchParams.get("code");
  const state = url.searchParams.get("state");

  // Three things have to line up: the state came back intact, it matches the
  // cookie we set, and it names the user whose session is making this request.
  // The last check is what stops a captured callback URL from being replayed
  // into someone else's browser to move a grant onto their account.
  if (!code || !state || !expectedState || !safeEqual(state, expectedState)) {
    return done(origin, "failed");
  }
  if (state.split(".")[1] !== user.id) return done(origin, "failed");

  // Re-checked after the round trip, not just before it — the flow takes as
  // long as the user takes, and both of these can change in the meantime.
  if (accountTooNew(user.createdAt)) return done(origin, "too_new");

  try {
    const tokenRes = await fetch(`${API}/oauth2/token`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        client_id: config.clientId,
        client_secret: config.clientSecret,
        grant_type: "authorization_code",
        code,
        redirect_uri: `${origin}/api/rewards/discord/callback`,
      }),
    });
    const tokens = (await tokenRes.json()) as TokenResponse;
    if (!tokenRes.ok || !tokens.access_token) return done(origin, "failed");

    const auth = { Authorization: `Bearer ${tokens.access_token}` };

    const meRes = await fetch(`${API}/users/@me`, { headers: auth });
    const me = (await meRes.json()) as DiscordUser;
    if (!meRes.ok || !me.id) return done(origin, "failed");

    // The verification itself. 200 means Discord returned a guild member
    // object for our guild — they are in it. 404 means they are not.
    const memberRes = await fetch(`${API}/users/@me/guilds/${config.guildId}/member`, {
      headers: auth,
    });

    if (memberRes.status === 404) return done(origin, "not_member");
    if (!memberRes.ok) {
      // Anything else — 401, 403, a 429 rate limit, a Discord outage — is an
      // INCONCLUSIVE answer, and inconclusive must never pay out. Fail closed
      // and tell the user to retry; a false negative costs a retry, a false
      // positive costs real money.
      console.error(`[rewards] Discord member check returned ${memberRes.status}`);
      return done(origin, "failed");
    }

    const hash = identityHash("discord", me.id);
    if (hash === null) {
      console.error("[rewards] KODELY_REWARDS_ID_SALT is not set — refusing to grant.");
      return done(origin, "unavailable");
    }

    const result = await grantReward(user.id, "discord", hash);
    if (result.ok) return done(origin, "discord_ok");

    switch (result.reason) {
      case "already_claimed":
        return done(origin, "already");
      // The Discord account itself has already earned this on some other
      // Kodely account. This is the check that stops one Discord login from
      // farming fifty signups, and it is the one that will actually fire.
      case "identity_already_used":
        return done(origin, "discord_taken");
      case "velocity_tripped":
        return done(origin, "paused");
      default:
        return done(origin, "unavailable");
    }
  } catch (err) {
    console.error("[rewards] Discord verification failed:", err);
    return done(origin, "failed");
  }
}

