import { redirect } from "next/navigation";
import Link from "next/link";
import { getCurrentUser } from "@/lib/auth";
import { getSpendCapStatus, spentInWindow } from "@/lib/credits";
import {
  MIN_ACCOUNT_AGE_HOURS,
  rewardStatuses,
  UNVERIFIED_HOLD_HOURS,
} from "@/app/api/rewards/_lib";
import RewardsCard from "@/components/rewards/RewardsCard";
import SpendCapForm from "./SpendCapForm";

export const dynamic = "force-dynamic";

export default async function SettingsPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const cap = await getSpendCapStatus(user.id);
  // getSpendCapStatus skips the spend query when uncapped (nothing to compare
  // against), but this page shows recent spend either way.
  const spent = cap.cap === null ? await spentInWindow(user.id) : cap.spent;

  // Returns [] when no reward is configured, so the card renders nothing at
  // all rather than this page needing to know anything about env vars.
  const rewards = await rewardStatuses(user);

  // Set by the Discord OAuth callback on its way back here.
  const notice = (await searchParams).reward;

  return (
    <div className="mx-auto max-w-2xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/dashboard"
          className="text-sm text-black/60 underline underline-offset-2 hover:no-underline dark:text-white/60"
        >
          ← Back
        </Link>
        <h1 className="mt-3 text-lg font-semibold tracking-tight">Settings</h1>
        <p className="text-sm text-black/60 dark:text-white/60">{user.email}</p>
      </div>

      <SpendCapForm initialCap={cap.cap} spent={spent} />

      <RewardsCard
        rewards={rewards}
        holdHours={UNVERIFIED_HOLD_HOURS}
        unlockHours={MIN_ACCOUNT_AGE_HOURS}
        notice={typeof notice === "string" ? notice : undefined}
      />
    </div>
  );
}

