export async function recordPending(
  userId: string,
  platform: Platform,
  hash: string,
): Promise<{ ok: true } | { ok: false; reason: Denial }> {
  const userLock = lockKey(`user:${userId}`);
  const identityLock = lockKey(`identity:${platform}:${hash}`);

  return db.$transaction(async (tx) => {
